1. Create src/main/db/index.ts:
   ```typescript
   import Database from 'better-sqlite3';
   import { drizzle } from 'drizzle-orm/better-sqlite3';
   import { app } from 'electron';
   import { existsSync, mkdirSync } from 'fs';
   import path from 'path';
   import * as schema from './schema';
   ```
2. Implement getDbPath function:
   ```typescript
   export function getDbPath(): string {
     const userDataPath = app.getPath('userData');
     // On macOS: ~/Library/Application Support/Flusk
     const dbDir = path.join(userDataPath);
     if (!existsSync(dbDir)) {
       mkdirSync(dbDir, { recursive: true });
     }
     return path.join(dbDir, 'flusk.db');
   }
   ```
3. Create database connection with pragmas for performance:
   ```typescript
   let _db: ReturnType<typeof drizzle> | null = null;
   let _sqlite: Database.Database | null = null;

   export function initDatabase(): ReturnType<typeof drizzle> {
     if (_db) return _db;
     const dbPath = getDbPath();
     _sqlite = new Database(dbPath);
     // Enable WAL mode for better concurrent performance
     _sqlite.pragma('journal_mode = WAL');
     // Enable foreign keys
     _sqlite.pragma('foreign_keys = ON');
     _db = drizzle(_sqlite, { schema });
     return _db;
   }

   export function getDb() {
     if (!_db) throw new Error('Database not initialized');
     return _db;
   }

   export function closeDatabase() {
     if (_sqlite) {
       _sqlite.close();
       _sqlite = null;
       _db = null;
     }
   }
   ```
4. Export schema types for IPC handlers
5. Call initDatabase() early in main process startup (before window creation)
6. Call closeDatabase() on app quit event

