1. Create src/main/ai/chat.ts with core chat logic:
   ```typescript
   import { streamText } from 'ai';

   export async function* sendMessage(content: string, sessionId: string) {
     const provider = createOpenRouterProvider(apiKey);
     const model = getModelInstance(provider);
     const systemPrompt = buildSystemPrompt(await getContext());

     const result = await streamText({
       model,
       system: systemPrompt,
       messages: await getChatHistory(sessionId),
       tools: toolCollection,
     });

     for await (const chunk of result.textStream) {
       yield { type: 'text', content: chunk };
     }
     // Handle tool calls
     for (const toolCall of result.toolCalls) {
       yield { type: 'tool', ...toolCall };
     }
   }
   ```
