Create src/main/shortcuts.ts with global shortcut registration:

1. Import required modules:
   ```typescript
   import { globalShortcut, BrowserWindow } from 'electron';
   ```

2. Implement registerGlobalShortcuts function:
   ```typescript
   export function registerGlobalShortcuts(mainWindow: BrowserWindow): void {
     // Toggle window visibility
     globalShortcut.register('CommandOrControl+Shift+Space', () => {
       toggleWindow(mainWindow);
     });

     // Quick add with clipboard
     globalShortcut.register('CommandOrControl+Shift+A', () => {
       showQuickAdd(mainWindow);
     });
   }
   ```

3. Implement toggleWindow function:
   ```typescript
   function toggleWindow(win: BrowserWindow): void {
     if (win.isVisible() && win.isFocused()) {
       win.hide();
     } else {
       win.show();
       win.focus();
     }
   }
   ```

