1. Create window position manager:
   ```typescript
   import { BrowserWindow, screen } from 'electron';
   import { db } from './db';

   interface WindowPosition {
     x: number;
     y: number;
     width: number;
     height: number;
   }

   let hasBeenPositioned = false;
   ```

2. Implement position logic on window show:
   ```typescript
   export function positionWindow(win: BrowserWindow): void {
     const savedPosition = getSavedPosition();

     if (savedPosition && hasBeenPositioned) {
       // Use saved position
       win.setBounds(savedPosition);
     } else {
       // Center on primary display
       const { width, height } = screen.getPrimaryDisplay().workAreaSize;
       const winBounds = win.getBounds();
       win.setPosition(
         Math.round((width - winBounds.width) / 2),
         Math.round((height - winBounds.height) / 2)
       );
       hasBeenPositioned = true;
     }
   }
   ```

3. Save position on window move/resize:
   ```typescript
   win.on('moved', () => saveWindowPosition(win));
   win.on('resized', () => saveWindowPosition(win));

   function saveWindowPosition(win: BrowserWindow): void {
     const bounds = win.getBounds();
     // Save to settings table in SQLite
     db.run('INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)', 
       ['windowPosition', JSON.stringify(bounds)]);
   }
   ```

