Create src/main/appLifecycle.ts for app lifecycle management:

1. Implement single instance lock at very start of main.ts:
   ```typescript
   const gotTheLock = app.requestSingleInstanceLock();

   if (!gotTheLock) {
     app.quit();
   } else {
     app.on('second-instance', (event, commandLine, workingDirectory) => {
       // Someone tried to run a second instance
       // Focus our window instead
       if (mainWindow) {
         if (mainWindow.isMinimized()) mainWindow.restore();
         mainWindow.show();
         mainWindow.focus();
       }
     });
   }
   ```

2. Implement launch at login:
   ```typescript
   export function setLaunchAtLogin(enabled: boolean): void {
     app.setLoginItemSettings({
       openAtLogin: enabled,
       openAsHidden: true,  // Start hidden in tray
       // macOS-specific: use launch agent
       path: app.getPath('exe'),
     });
   }

   export function getLaunchAtLoginStatus(): boolean {
     return app.getLoginItemSettings().openAtLogin;
   }
   ```

